cpp.setup:
auto* control = new fluent::collections::SplitView(%PARENT%);
for (const auto& entry : {QPair<QString, QString>{QStringLiteral("Navigation"), QStringLiteral("Folders, saved views and quick filters.")}, {QStringLiteral("Workspace"), QStringLiteral("Active document canvas and inspector details.")}}) {
    auto* pane = new fluent::layout::Card;
    auto* lay = new QVBoxLayout(pane);
    lay->setContentsMargins(16, 14, 16, 14);
    lay->setSpacing(6);
    auto* title = new fluent::textfields::Label(entry.first, pane);
    title->setFluentTypography(Typography::FontRole::Subtitle);
    lay->addWidget(title);
    auto* summary = new fluent::textfields::Label(entry.second, pane);
    summary->setWordWrap(true);
    summary->setTextColorRole(fluent::textfields::Label::TextColorRole::Secondary);
    lay->addWidget(summary);
    lay->addStretch();
    control->addPane(pane, fluent::WidgetOwnership::Owned);
}
control->setPanePreferredSize(0, 220);
control->setPanePreferredSize(1, 294);
control->setPaneFill(1, true);
